import assert from 'node:assert/strict'
import { execFileSync, spawn } from 'node:child_process'
import { existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs'

const BASE='http://127.0.0.1:4173/catfood_web/'
const TARGET_SHA=process.env.TARGET_SHA
const OUT='qa-artifacts'
const STORAGE_KEY='catfood.switch-session.v1'
const LONG_NAME='울트라 프로틴+ 스킨 & 코트 & 다이제스티브 캣 레시피'
const DIRECT_IDS=['product_b47d3ae674773585','product_99c5ee4eb9211a75','product_7729d5c3a145ffd6','product_06cc1df5a4cec6f6','product_e2df0243fd9a3e68']
mkdirSync(OUT,{recursive:true})
assert.ok(TARGET_SHA)
const sleep=ms=>new Promise(r=>setTimeout(r,ms))
const js=v=>JSON.stringify(v)

class Cdp{
  constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map();this.requests=[]}
  async connect(){
    this.ws=new WebSocket(this.url)
    await new Promise((r,j)=>{const t=setTimeout(()=>j(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);r()},{once:true});this.ws.addEventListener('error',()=>j(new Error('ws error')),{once:true})})
    this.ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Network.requestWillBeSent')this.requests.push({url:m.params.request.url,method:m.params.request.method});const p=m.id?this.pending.get(m.id):null;if(!p)return;this.pending.delete(m.id);m.error?p.j(new Error(m.error.message)):p.r(m.result)})
    for(const x of ['Page.enable','Runtime.enable','DOM.enable','CSS.enable','Network.enable'])await this.send(x)
    await this.send('Emulation.setLocaleOverride',{locale:'ko-KR'})
    await this.send('Page.addScriptToEvaluateOnNewDocument',{source:`(()=>{const nativeFetch=window.fetch.bind(window);window.__qaBlockedAnalytics=0;window.__qaBlockedWrites=0;window.fetch=(input,init={})=>{const url=typeof input==='string'?input:(input&&input.url)||'';const method=String(init.method||(input&&input.method)||'GET').toUpperCase();if(url.includes('/functions/v1/decision-intake')){window.__qaBlockedAnalytics+=1;return Promise.resolve(new Response(null,{status:204}))}if(url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(method)){window.__qaBlockedWrites+=1;return Promise.resolve(new Response(null,{status:204}))}return nativeFetch(input,init)}})();`})
  }
  send(method,params={}){const id=this.id++;return new Promise((r,j)=>{this.pending.set(id,{r,j});this.ws.send(JSON.stringify({id,method,params}))})}
  async eval(expression){const x=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(x.exceptionDetails)throw new Error(x.exceptionDetails.exception?.description||x.exceptionDetails.text);return x.result?.value}
  async wait(expression,label,ms=40000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}
  async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root');await this.eval('document.fonts?.ready');await sleep(220)}
  async shot(path){await this.eval('document.fonts?.ready');await sleep(80);const x=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(x.data,'base64'))}
  async fonts(selector){const {root}=await this.send('DOM.getDocument',{depth:1});const {nodeId}=await this.send('DOM.querySelector',{nodeId:root.nodeId,selector});assert.ok(nodeId,`font node missing ${selector}`);return (await this.send('CSS.getPlatformFontsForNode',{nodeId})).fonts??[]}
  close(){try{this.ws?.close()}catch{}}
}

async function launch(width,height){
  const chrome='/usr/bin/google-chrome';assert.ok(existsSync(chrome),'Chrome unavailable')
  const port=9700+(process.pid%120)+(width%37),dir=`/tmp/pr24-${width}-${height}-${process.pid}-${Math.random().toString(36).slice(2)}`
  rmSync(dir,{recursive:true,force:true})
  const proc=spawn(chrome,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--disable-cache',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'})
  for(let i=0;i<200;i++){
    try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json(),p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p){const c=new Cdp(p.webSocketDebuggerUrl);await c.connect();const mobile=width<=760;await c.send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile,screenWidth:width,screenHeight:height});await c.send('Emulation.setUserAgentOverride',{userAgent:mobile?'Mozilla/5.0 (Linux; Android 16; Mobile) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Mobile Safari/537.36':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Safari/537.36',acceptLanguage:'ko-KR,ko;q=0.9,en;q=0.8',platform:mobile?'Android':'Linux x86_64'});return{c,proc,dir,version:execFileSync(chrome,['--version'],{encoding:'utf8'}).trim()}}}catch{}await sleep(100)
  }
  throw new Error('Chrome launch timeout')
}

const state=c=>c.eval(`(()=>{const r=sessionStorage.getItem(${js(STORAGE_KEY)});return r?JSON.parse(r).state:null})()`)
const waitState=(c,expr,label)=>c.wait(`(()=>{const r=sessionStorage.getItem(${js(STORAGE_KEY)});if(!r)return false;const s=JSON.parse(r).state;return ${expr}})()`,label)
async function setQuery(c,value){const ok=await c.eval(`(()=>{const e=document.querySelector('.switch-find-search input');if(!e)return false;Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,${js(value)});e.dispatchEvent(new Event('input',{bubbles:true}));return true})()`);assert.equal(ok,true);await c.wait(`document.querySelector('.switch-find-search input')?.value===${js(value)}`,'query');await sleep(220)}
async function clickExact(c,scope,text){await c.wait(`(()=>{const r=document.querySelector(${js(scope)});return r&&[...r.querySelectorAll('button')].some(b=>b.textContent.trim()===${js(text)}&&!b.disabled)})()`,`button ${text}`);const ok=await c.eval(`(()=>{const r=document.querySelector(${js(scope)}),b=[...r.querySelectorAll('button')].find(x=>x.textContent.trim()===${js(text)}&&!x.disabled);if(!b)return false;b.scrollIntoView({block:'center',inline:'nearest'});b.click();return true})()`);assert.equal(ok,true);await sleep(160)}
async function clickContains(c,selector,text){await c.wait(`[...document.querySelectorAll(${js(selector)})].some(n=>n.textContent.includes(${js(text)}))`,`contains ${text}`);const ok=await c.eval(`(()=>{const n=[...document.querySelectorAll(${js(selector)})].find(x=>x.textContent.includes(${js(text)}));if(!n)return false;n.scrollIntoView({block:'center',inline:'nearest'});n.click();return true})()`);assert.equal(ok,true);await sleep(160)}
async function clickButtonContains(c,scope,text){await c.wait(`(()=>{const r=document.querySelector(${js(scope)});return r&&[...r.querySelectorAll('button')].some(b=>b.textContent.includes(${js(text)})&&!b.disabled)})()`,`button contains ${text}`);const ok=await c.eval(`(()=>{const r=document.querySelector(${js(scope)}),b=[...r.querySelectorAll('button')].find(x=>x.textContent.includes(${js(text)})&&!x.disabled);if(!b)return false;b.scrollIntoView({block:'center',inline:'nearest'});b.click();return true})()`);assert.equal(ok,true);await sleep(160)}
async function pointerClick(c,selector,index=0){
  const prep=await c.eval(`(()=>{const n=document.querySelectorAll(${js(selector)})[${index}];if(!n)return null;const r=n.getBoundingClientRect();window.scrollTo({top:Math.max(0,scrollY+r.top-innerHeight/2+r.height/2),behavior:'instant'});return true})()`);assert.ok(prep,`pointer target missing ${selector}[${index}]`);await sleep(100)
  const info=await c.eval(`(()=>{const n=document.querySelectorAll(${js(selector)})[${index}],r=n.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=document.elementFromPoint(x,y);return{text:n.textContent.trim(),rect:[r.left,r.top,r.width,r.height],x,y,centerHit:h===n||n.contains(h),hit:h?.className||h?.tagName}})()`);assert.equal(info.centerHit,true,`pointer target occluded ${selector}[${index}]: ${JSON.stringify(info)}`);assert.ok(info.x>=0&&info.x<await c.eval('innerWidth')&&info.y>=0&&info.y<await c.eval('innerHeight'),`pointer target outside viewport ${JSON.stringify(info)}`)
  await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:info.x,y:info.y,button:'left',clickCount:1});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:info.x,y:info.y,button:'left',clickCount:1});await sleep(180);return info
}
async function assertNetwork(c){const sentAnalytics=c.requests.filter(r=>r.url.includes('/functions/v1/decision-intake')),sentWrites=c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(r.method));assert.equal(sentAnalytics.length,0,'analytics escaped blocker');assert.equal(sentWrites.length,0,'production write escaped blocker');return{blocked:await c.eval(`({analytics:window.__qaBlockedAnalytics||0,writes:window.__qaBlockedWrites||0})`),sentAnalytics:sentAnalytics.length,sentWrites:sentWrites.length,publicReads:c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&r.method==='GET').length}}

async function revealColumn(c,index){
  const first=await c.eval(`(()=>{const w=document.querySelector('.compare-table-wrap'),label=document.querySelector('.compare-corner'),head=document.querySelectorAll('.compare-product-head')[${index}];if(!w||!label||!head)return null;const l=label.getBoundingClientRect(),h=head.getBoundingClientRect(),max=w.scrollWidth-w.clientWidth,target=Math.max(0,Math.min(max,w.scrollLeft+h.left-l.right));w.scrollLeft=target;return{target,max}})()`);assert.ok(first,`column ${index} missing`);await sleep(140)
  return c.eval(`(()=>{const w=document.querySelector('.compare-table-wrap'),label=document.querySelector('.compare-corner'),head=document.querySelectorAll('.compare-product-head')[${index}],wr=w.getBoundingClientRect(),lr=label.getBoundingClientRect(),hr=head.getBoundingClientRect();return{scrollLeft:w.scrollLeft,max:w.scrollWidth-w.clientWidth,wrap:[wr.left,wr.right,wr.width],label:[lr.left,lr.right,lr.width],head:[hr.left,hr.right,hr.width],readable:hr.left>=lr.right-1&&hr.right<=wr.right+1}})()`)
}
async function tabPointer(c,label){const index=await c.eval(`[...document.querySelectorAll('.compare-tabs button')].findIndex(b=>b.textContent.trim()===${js(label)})`);assert.ok(index>=0,`tab missing ${label}`);return pointerClick(c,'.compare-tabs button',index)}
async function waitTab(c,key){if(key==='nutrition')await c.wait(`!document.body.innerText.includes('영양 정보를 불러오는 중입니다.')&&!document.querySelector('.compare-state.is-error')&&document.querySelector('.compare-row.is-metric')`,'nutrition complete');if(key==='ingredients')await c.wait(`!document.body.innerText.includes('원재료 정보를 불러오는 중입니다.')&&!document.querySelector('.compare-state.is-error')&&document.querySelector('.compare-ingredient-text')`,'ingredients complete');await sleep(160)}
async function lastRowMetric(c,labelText,count){return c.eval(`(()=>{const row=[...document.querySelectorAll('.compare-row')].find(r=>r.querySelector('.compare-row-label')?.textContent.trim()===${js(labelText)});if(!row)return null;const label=row.querySelector('.compare-row-label'),cell=row.querySelectorAll('.compare-cell')[${count-1}],lr=label.getBoundingClientRect(),cr=cell.getBoundingClientRect(),s=getComputedStyle(cell);return{label:[lr.left,lr.right,lr.width],cell:[cr.left,cr.right,cr.width],text:cell.textContent.trim().replace(/\\s+/g,' '),clientWidth:cell.clientWidth,scrollWidth:cell.scrollWidth,overflow:s.overflow,textOverflow:s.textOverflow,readable:cr.left>=lr.right-1}})()`)}

async function directCase(width,height,count,{fullTabs=true,pointerDetail=false}={}){
  const {c,proc,dir,version}=await launch(width,height);const prefix=`matrix-${width}x${height}-${count}`,result={width,height,count,chrome:version,captures:[]}
  try{
    const ids=DIRECT_IDS.slice(0,count);await c.nav(`${BASE}?view=workspace&applied=1&compare=${ids.join(',')}&compareOpen=1&compareTab=overview`);await c.wait(`document.querySelectorAll('.compare-product-head').length===${count}`,'compare heads');result.fonts=await c.fonts('.compare-product-copy>strong');assert.ok(result.fonts.some(f=>f.familyName.includes('Noto Sans CJK KR')),'Korean font mismatch')
    result.base=await c.eval(`(()=>{const w=document.querySelector('.compare-table-wrap'),t=document.querySelector('.compare-table'),corner=document.querySelector('.compare-corner'),wr=w.getBoundingClientRect(),tr=t.getBoundingClientRect(),cr=corner.getBoundingClientRect(),heads=[...document.querySelectorAll('.compare-product-head')].map(n=>n.getBoundingClientRect().width);return{innerWidth,docWidth:document.documentElement.scrollWidth,wrap:{rect:[wr.left,wr.right,wr.width],clientWidth:w.clientWidth,scrollWidth:w.scrollWidth,max:w.scrollWidth-w.clientWidth},table:{width:tr.width,minWidth:getComputedStyle(t).minWidth},cornerWidth:cr.width,headWidths:heads}})()`);assert.ok(result.base.docWidth<=result.base.innerWidth+1,`document overflow ${JSON.stringify(result.base)}`)
    if(width<=760){assert.ok(Math.abs(result.base.cornerWidth-108)<=1,`mobile corner width ${result.base.cornerWidth}`);for(const value of result.base.headWidths)assert.ok(Math.abs(value-190)<=1,`mobile product width ${value}`);assert.ok(Math.abs(result.base.table.width-(108+190*count))<=2,`mobile table width ${JSON.stringify(result.base.table)}`)}
    result.columns=[];for(let i=0;i<count;i++){const pos=await revealColumn(c,i);result.columns.push(pos);assert.equal(pos.readable,true,`column ${i} cannot be fully read: ${JSON.stringify(pos)}`)}
    result.overviewRight=await revealColumn(c,count-1);result.lastControls=await c.eval(`(()=>{const head=document.querySelectorAll('.compare-product-head')[${count-1}],detail=head.querySelector('.compare-detail-link'),remove=head.querySelector('.compare-remove');const H=n=>{const r=n.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=document.elementFromPoint(x,y);return{text:n.textContent.trim(),rect:[r.left,r.top,r.width,r.height],centerHit:h===n||n.contains(h),hit:h?.className||h?.tagName}};return{detail:H(detail),remove:H(remove)}})()`);assert.equal(result.lastControls.detail.centerHit,true,`detail occluded ${JSON.stringify(result.lastControls)}`);assert.equal(result.lastControls.remove.centerHit,true,`remove occluded ${JSON.stringify(result.lastControls)}`);await c.shot(`${OUT}/${prefix}-overview-right.png`);result.captures.push(`${prefix}-overview-right.png`)
    if(pointerDetail){await revealColumn(c,count-1);result.pointerDetail=await pointerClick(c,'.compare-detail-link',count-1);await c.wait(`document.querySelector('.detail-stage')`,'pointer detail open');await c.shot(`${OUT}/${prefix}-detail-pointer.png`);result.captures.push(`${prefix}-detail-pointer.png`);await pointerClick(c,'.detail-topbar button',0);await c.wait(`document.querySelector('.compare-stage')`,'detail return');await sleep(120)}
    if(fullTabs){
      await tabPointer(c,'영양');await waitTab(c,'nutrition');await revealColumn(c,count-1);result.energy=await lastRowMetric(c,'열량',count);assert.ok(result.energy&&result.energy.readable,`energy occluded ${JSON.stringify(result.energy)}`);assert.ok(result.energy.text.length>0,'energy text empty');await c.shot(`${OUT}/${prefix}-nutrition-right.png`);result.captures.push(`${prefix}-nutrition-right.png`)
      await tabPointer(c,'원재료');await waitTab(c,'ingredients');await revealColumn(c,count-1);result.ingredients=await lastRowMetric(c,'출처 원문',count);assert.ok(result.ingredients&&result.ingredients.readable,`ingredients occluded ${JSON.stringify(result.ingredients)}`);const raw=await c.eval(`(()=>{const row=[...document.querySelectorAll('.compare-row')].find(r=>r.querySelector('.compare-row-label')?.textContent.trim()==='출처 원문'),cell=row?.querySelectorAll('.compare-cell')[${count-1}],texts=cell?[...cell.querySelectorAll('.compare-ingredient-text')]:[];return texts.map(n=>({text:n.textContent.trim(),clientWidth:n.clientWidth,scrollWidth:n.scrollWidth,clientHeight:n.clientHeight,scrollHeight:n.scrollHeight,overflowY:getComputedStyle(n).overflowY}))})()`);result.rawIngredients=raw;assert.ok(raw.length>=1,'ingredient raw text missing');assert.ok(raw.every(x=>x.scrollWidth<=x.clientWidth+1),`ingredient horizontal clipping ${JSON.stringify(raw)}`);await c.shot(`${OUT}/${prefix}-ingredients-right.png`);result.captures.push(`${prefix}-ingredients-right.png`)
    }
    result.network=await assertNetwork(c);return result
  }finally{c.close();proc.kill('SIGTERM');await sleep(120);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
}

async function establishResults(c,result){
  await c.nav(`${BASE}?view=workspace&mode=switch`);await c.wait(`document.querySelector('.switch-find-search input')`,'switch search');await c.wait(`!document.body.innerText.includes('제품 목록을 불러오는 중입니다.')`,'catalog load')
  await setQuery(c,'AATU 연어');await c.wait(`document.querySelectorAll('.switch-find-result').length>0`,'AATU result');await clickContains(c,'.switch-find-result','연어');await c.wait(`document.querySelector('.switch-current-preview')`,'current preview');await clickExact(c,'.switch-current-preview','이 제품을 현재 사료로 선택 →');await waitState(c,`s.step==='sku'`,'sku step');await c.wait(`document.querySelector('.switch-sku-option')&&!document.body.innerText.includes('판매 규격을 불러오는 중입니다.')`,'sku loaded');await clickContains(c,'.switch-sku-option','1 kg');await waitState(c,`s.variantSelection?.kind==='variant'`,'variant selected');result.selection=await state(c)
  await clickExact(c,'.switch-step-actions','다음 →');await waitState(c,`s.step==='change'`,'change');await clickExact(c,'.switch-step-main','다른 브랜드로 보기');await waitState(c,`s.changeBrand===true`,'change brand');await clickExact(c,'.switch-step-actions','다음 →');await waitState(c,`s.step==='keep'`,'keep');await clickExact(c,'.switch-step-main','건식 유지');await waitState(c,`s.keep?.feedType==='건식'`,'keep dry');await clickExact(c,'.switch-step-actions','후보 제품 보기 →');await waitState(c,`s.step==='results'`,'results');await c.wait(`document.querySelectorAll('.switch-candidate-row').length>=5`,'candidate rows')
}
async function addSelected(c){const before=await state(c),n=before.compareIds.length;await clickButtonContains(c,'.switch-inspector-actions','비교에 추가');await waitState(c,`s.compareIds.length===${n+1}`,'compare add');const after=await state(c);return after.compareIds.at(-1)}
async function addCandidates(c,target){const added=[];await clickContains(c,'.switch-candidate-row',LONG_NAME);await c.wait(`document.querySelector('.switch-candidate-inspector h1')?.textContent.includes(${js(LONG_NAME)})`,'long inspector');added.push({name:LONG_NAME,id:await addSelected(c)});const count=await c.eval(`document.querySelectorAll('.switch-candidate-row').length`);for(let i=0;i<count&&added.length<target;i++){const row=await c.eval(`(()=>{const n=document.querySelectorAll('.switch-candidate-row')[${i}];return n?{name:n.querySelector('.switch-candidate-identity strong')?.textContent.trim()||''}:null})()`);if(!row||row.name===LONG_NAME)continue;await c.eval(`(()=>{const n=document.querySelectorAll('.switch-candidate-row')[${i}];n.scrollIntoView({block:'center'});n.click();return true})()`);await sleep(140);const s=await state(c);if(s.compareIds.includes(s.selectedCandidateId))continue;added.push({name:row.name,id:await addSelected(c)})}assert.equal(added.length,target,`could not add ${target}`);return added}

async function switchStateCase(width,height,target){
  const {c,proc,dir,version}=await launch(width,height);const prefix=`state-${width}x${height}-${target}`,result={width,height,target,chrome:version,captures:[]}
  try{
    await establishResults(c,result);result.added=await addCandidates(c,target);result.compareIds=[...(await state(c)).compareIds];await clickButtonContains(c,'.switch-compare-dock','비교 보기');await waitState(c,`s.compareOpen===true&&s.compareIds.length===${target}`,'compare open');await c.wait(`document.querySelectorAll('.compare-product-head').length===${target}`,'compare heads')
    await tabPointer(c,'원재료');await waitState(c,`s.compareTab==='ingredients'`,'ingredients state');await waitTab(c,'ingredients');await revealColumn(c,0);const before=await state(c);result.beforeDetail={compareIds:[...before.compareIds],compareTab:before.compareTab};result.detailPointer=await pointerClick(c,'.compare-detail-link',0);await c.wait(`document.querySelector('.detail-stage')`,'detail opened by pointer');const inDetail=await state(c);result.inDetail={compareIds:[...inDetail.compareIds],compareTab:inDetail.compareTab,detailProductId:inDetail.detailProductId};await c.shot(`${OUT}/${prefix}-detail.png`);result.captures.push(`${prefix}-detail.png`);await pointerClick(c,'.detail-topbar button',0);await c.wait(`document.querySelector('.compare-stage')`,'compare returned');await waitState(c,`s.compareOpen===true&&s.compareTab==='ingredients'`,'compare state preserved');const after=await state(c);result.afterDetail={compareIds:[...after.compareIds],compareTab:after.compareTab,detailProductId:after.detailProductId};assert.deepEqual(result.afterDetail.compareIds,result.beforeDetail.compareIds,'compare IDs changed after detail');assert.equal(result.afterDetail.compareTab,'ingredients','compare tab changed after detail');await c.shot(`${OUT}/${prefix}-detail-return.png`);result.captures.push(`${prefix}-detail-return.png`)
    await tabPointer(c,'개요');await waitState(c,`s.compareTab==='overview'`,'overview state');await revealColumn(c,0);const removed=(await state(c)).compareIds[0];result.removeOne={removed,pointer:await pointerClick(c,'.compare-remove',0)};await waitState(c,`s.compareIds.length===${target-1}`,'remove one');assert.equal((await state(c)).compareIds.includes(removed),false,'removed ID still present');await c.shot(`${OUT}/${prefix}-after-remove.png`);result.captures.push(`${prefix}-after-remove.png`)
    await clickButtonContains(c,'.compare-header','제품 목록으로');await c.wait(`document.querySelector('.switch-results-stage')`,'results return');await waitState(c,`s.compareOpen===false&&s.compareIds.length===${target-1}`,'results preserved');result.resultsState=await state(c);await c.shot(`${OUT}/${prefix}-results.png`);result.captures.push(`${prefix}-results.png`)
    if(target-1>0){await clickButtonContains(c,'.switch-compare-dock','비교 보기');await c.wait(`document.querySelector('.compare-stage')`,'compare reentry');await waitState(c,`s.compareIds.length===${target-1}`,'reentry IDs');result.reentry=await state(c);await c.shot(`${OUT}/${prefix}-reentry.png`);result.captures.push(`${prefix}-reentry.png`)}
    if(target===2){const remaining=(await state(c)).compareIds[0];await revealColumn(c,0);result.removeLast={removed:remaining,pointer:await pointerClick(c,'.compare-remove',0)};await c.wait(`document.querySelector('.switch-results-stage')`,'empty compare closes');await waitState(c,`s.compareIds.length===0&&s.compareOpen===false`,'empty compare');result.empty=await state(c);await c.shot(`${OUT}/${prefix}-empty.png`);result.captures.push(`${prefix}-empty.png`);await c.eval('history.back()');await sleep(450);result.afterBack=await state(c);assert.equal(result.afterBack.compareIds.length,0,'removed compare revived after browser back');await c.shot(`${OUT}/${prefix}-browser-back.png`);result.captures.push(`${prefix}-browser-back.png`)}else{await c.eval('history.back()');await sleep(450);result.afterBack=await state(c);assert.equal(result.afterBack.compareIds.includes(removed),false,'removed compare revived after browser back')}
    if(target===5){const longHead=await c.eval(`(()=>{const n=[...document.querySelectorAll('.compare-product-copy>strong')].find(x=>x.textContent.trim()===${js(LONG_NAME)});if(!n)return null;const r=n.getBoundingClientRect();return{text:n.textContent.trim(),clientWidth:n.clientWidth,scrollWidth:n.scrollWidth,clientHeight:n.clientHeight,scrollHeight:n.scrollHeight,rect:[r.left,r.top,r.width,r.height],whiteSpace:getComputedStyle(n).whiteSpace,textOverflow:getComputedStyle(n).textOverflow}})()`);result.longName=longHead;if(longHead){assert.ok(longHead.scrollWidth<=longHead.clientWidth+1,'long name horizontally clipped');assert.notEqual(longHead.textOverflow,'ellipsis','long name ellipsized')}}
    result.network=await assertNetwork(c);return result
  }finally{c.close();proc.kill('SIGTERM');await sleep(120);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
}

const report={targetSha:TARGET_SHA,environment:{kind:'GitHub-hosted headless Chrome responsive/mobile emulation; not physical devices',locale:'ko-KR'},status:'running',matrix:[],boundaries:[],state:[],error:null}
const save=()=>writeFileSync(`${OUT}/report.json`,JSON.stringify(report,null,2))
try{
  for(const width of [360,390])for(const count of [1,2,5]){report.matrix.push(await directCase(width,width===360?844:900,count,{fullTabs:true,pointerDetail:(width===360&&count===2)||(width===390&&count===5)}));save()}
  report.boundaries.push(await directCase(760,900,2,{fullTabs:false}));save();report.boundaries.push(await directCase(761,900,2,{fullTabs:false}));save();report.boundaries.push(await directCase(1280,900,2,{fullTabs:false}));save()
  const b760=report.boundaries[0],b761=report.boundaries[1],b1280=report.boundaries[2];assert.ok(Math.abs(b760.base.cornerWidth-108)<=1&&b760.base.headWidths.every(v=>Math.abs(v-190)<=1),'760 mobile grid missing');assert.ok(b761.base.cornerWidth>=170&&b761.base.headWidths.every(v=>v>=204),'761 desktop grid unexpectedly mobile');assert.ok(b1280.base.docWidth<=1280+1,'1280 document overflow')
  report.state.push(await switchStateCase(360,844,2));save();report.state.push(await switchStateCase(390,900,5));save()
  report.status='pass';save();console.log('PR24_MOBILE_COMPARE_QA_PASS '+JSON.stringify({targetSha:TARGET_SHA,matrix:report.matrix.map(x=>({width:x.width,count:x.count,table:x.base.table.width,headWidths:x.base.headWidths,maxScroll:x.base.wrap.max,last:x.overviewRight,lastControls:x.lastControls,energy:x.energy&&x.energy.text,ingredient:x.ingredients&&x.ingredients.text.slice(0,80),network:x.network})),boundaries:report.boundaries.map(x=>({width:x.width,corner:x.base.cornerWidth,heads:x.base.headWidths,docWidth:x.base.docWidth,maxScroll:x.base.wrap.max})),state:report.state.map(x=>({width:x.width,target:x.target,ids:x.compareIds,afterDetail:x.afterDetail,removed:x.removeOne?.removed,empty:x.empty?.compareIds,afterBack:x.afterBack?.compareIds,network:x.network}))}))
}catch(e){report.status='fail';report.error=String(e?.stack||e);save();throw e}
